	"09170100": {
		names: [{ nominative: "Αγία Λουκία η χήρα και Γεμινιανός ο γιος της", short: "Αγία Λουκία" }],
		biographies: [
			{
				id: "saintgr",
				copyright: "saint.gr",
				text: "Η Αγία Λούκια ήταν πλούσια Ρωμαία κατά την εποχή των βασιλέων Διοκλητιανού (284 - 304 μ.Χ.) και Μαξιμιανού (286 - 305 μ.Χ.).<br/><br/>Μετά 36 χρόνια χηρείας και σε ηλικία 75 χρονών, προδόθηκε από τον ειδωλολάτρη γιο της Ευτρόπιο, στον Διοκλητιανό, ότι πιστεύει στον Χριστό. Τότε η Αγία συνελήφθη και κλείστηκε στη φυλακή. Εκεί υπέστη σκληρά βασανιστήρια, αλλά με τη χάρη του Θεού παρέμεινε αβλαβής και περιφερόταν στην πόλη για να αποδοκιμάσει μ' αυτό τον τρόπο την μικρότητα των βασανιστών της.<br/><br/>Το είδε αυτό ο Γερμινιανός (ή Γεμινιανός), πίστεψε στον Χριστό και μαζί με την Λούκια παρουσιάστηκε στον βασιλιά, ομολογώντας τον Χριστό.<br/><br/>Η Λούκια υιοθέτησε τον Γερμινιανό, τον βάπτισε και αφοί απαλλάχτηκαν από τους βασανιστές τους, έφυγαν στο Ταυρομένιο της Σικελίας. Αλλά εκεί, λόγω διωγμού, η Λούκια τράβηξε για τα βουνά, όπου απεβίωσε ειρηνικά. Ο δε Γερμινιανός συνελήφθη και αποκεφαλίστηκε.",
			},
		],
		info: [],
		refs: [],
		services: [],
		hymns: [],
	},
